/*
 * prog31_gcd_lcm – reproduced from the analysed binary
 *
 * Behaviour (as observed from the original executable):
 *
 *   * If fewer than two numeric arguments are supplied:
 *         prints "USAGE" and exits.
 *
 *   * The two arguments are parsed as signed decimal integers.
 *     If either argument contains non‑numeric characters,
 *     or the conversion fails, the program prints "BAD_INPUT".
 *
 *   * If either argument is LLONG_MIN (the most negative 64‑bit value)
 *     the absolute value cannot be represented – the program prints
 *     "OVERFLOW".
 *
 *   * After conversion the absolute values of the numbers are taken.
 *     If either absolute value is larger than 1 000 000 the program
 *     prints "OUT_OF_RANGE".
 *
 *   * If both numbers are zero the program prints "gcd=0 lcm=0".
 *
 *   * Otherwise it computes the greatest common divisor (GCD) of the
 *     absolute values using the Euclidean algorithm and the least
 *     common multiple (LCM) as  (|a|/gcd) * |b| .
 *     The result is printed as:
 *
 *         gcd=%ld lcm=%ld\n
 *
 *   * The program then terminates normally.
 *
 * The implementation below follows the same logic, using only standard
 * C library facilities, and therefore reproduces the exact observable
 * output of the original binary.
 */

#include <stdio.h>
#include <stdlib.h>
#include <limits.h>
#include <errno.h>

/* Euclidean algorithm for non‑negative numbers */
static long long gcd_ll(long long a, long long b)
{
    while (b != 0) {
        long long r = a % b;
        a = b;
        b = r;
    }
    return a;
}

/* Helper to test whether a string represents a valid decimal integer */
static int parse_long_long(const char *s, long long *out)
{
    char *endptr = NULL;
    errno = 0;
    *out = strtoll(s, &endptr, 10);

    /* No conversion performed */
    if (endptr == s)
        return 0;

    /* Trailing characters after the number */
    if (*endptr != '\0')
        return 0;

    /* Detect overflow/underflow reported by strtoll */
    if (errno == ERANGE)
        return 0;

    return 1;
}

int main(int argc, char *argv[])
{
    /* -----------------------------------------------------------------
     *  Argument count check
     * ----------------------------------------------------------------- */
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    /* -----------------------------------------------------------------
     *  Parse the two arguments
     * ----------------------------------------------------------------- */
    long long a, b;
    if (!parse_long_long(argv[1], &a) || !parse_long_long(argv[2], &b)) {
        puts("BAD_INPUT");
        return 0;
    }

    /* -----------------------------------------------------------------
     *  Overflow detection for absolute value (LLONG_MIN cannot be negated)
     * ----------------------------------------------------------------- */
    if (a == LLONG_MIN || b == LLONG_MIN) {
        puts("OVERFLOW");
        return 0;
    }

    /* -----------------------------------------------------------------
     *  Work with absolute values from now on
     * ----------------------------------------------------------------- */
    long long abs_a = (a < 0) ? -a : a;
    long long abs_b = (b < 0) ? -b : b;

    /* -----------------------------------------------------------------
     *  Range check (|value| must be ≤ 1 000 000)
     * ----------------------------------------------------------------- */
    if (abs_a > 1000000LL || abs_b > 1000000LL) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* -----------------------------------------------------------------
     *  Special case: both numbers are zero
     * ----------------------------------------------------------------- */
    if (abs_a == 0 && abs_b == 0) {
        puts("gcd=0 lcm=0");
        return 0;
    }

    /* -----------------------------------------------------------------
     *  Compute GCD and LCM
     * ----------------------------------------------------------------- */
    long long g = gcd_ll(abs_a, abs_b);
    /* LCM = (|a| / gcd) * |b| – safe from overflow because the product
       is guaranteed to fit in 64‑bit signed range for the allowed inputs. */
    long long l = (abs_a / g) * abs_b;

    printf("gcd=%ld lcm=%ld\n", g, l);
    return 0;
}
